CREATE TYPE "CircleVisibility" AS ENUM ('ORGANIZATION','DEPARTMENT','MEMBERS'); CREATE TYPE "CircleStatus" AS ENUM ('OPEN','CLOSED'); CREATE TYPE "CircleMemberRole" AS ENUM ('OWNER','MEMBER'); CREATE TYPE "CircleJoinStatus" AS ENUM ('PENDING','APPROVED','REJECTED');
CREATE TABLE "circles" ("id" UUID NOT NULL,"organization_id" UUID NOT NULL,"owner_id" UUID NOT NULL,"owner_department_id" UUID,"title" TEXT NOT NULL,"topic" TEXT NOT NULL,"visibility" "CircleVisibility" NOT NULL DEFAULT 'ORGANIZATION',"status" "CircleStatus" NOT NULL DEFAULT 'OPEN',"opportunity_id" UUID,"business_request_id" UUID,"project_id" UUID,"closes_at" TIMESTAMP(3),"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL,CONSTRAINT "circles_pkey" PRIMARY KEY ("id"));
CREATE TABLE "circle_members" ("circle_id" UUID NOT NULL,"user_id" UUID NOT NULL,"role" "CircleMemberRole" NOT NULL DEFAULT 'MEMBER',"joined_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"left_at" TIMESTAMP(3),CONSTRAINT "circle_members_pkey" PRIMARY KEY ("circle_id","user_id"));
CREATE TABLE "circle_join_requests" ("id" UUID NOT NULL,"circle_id" UUID NOT NULL,"applicant_id" UUID NOT NULL,"message" TEXT,"status" "CircleJoinStatus" NOT NULL DEFAULT 'PENDING',"reviewed_by_id" UUID,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL,CONSTRAINT "circle_join_requests_pkey" PRIMARY KEY ("id"));
CREATE TABLE "circle_discussions" ("id" UUID NOT NULL,"circle_id" UUID NOT NULL,"author_id" UUID NOT NULL,"content" TEXT NOT NULL,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "circle_discussions_pkey" PRIMARY KEY ("id"));
CREATE INDEX "circles_organization_id_status_created_at_idx" ON "circles"("organization_id","status","created_at"); CREATE INDEX "circle_members_user_id_left_at_idx" ON "circle_members"("user_id","left_at"); CREATE UNIQUE INDEX "circle_join_requests_circle_id_applicant_id_key" ON "circle_join_requests"("circle_id","applicant_id"); CREATE INDEX "circle_join_requests_circle_id_status_idx" ON "circle_join_requests"("circle_id","status"); CREATE INDEX "circle_discussions_circle_id_created_at_idx" ON "circle_discussions"("circle_id","created_at");
ALTER TABLE "circle_members" ADD CONSTRAINT "circle_members_circle_id_fkey" FOREIGN KEY ("circle_id") REFERENCES "circles"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "circle_join_requests" ADD CONSTRAINT "circle_join_requests_circle_id_fkey" FOREIGN KEY ("circle_id") REFERENCES "circles"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "circle_discussions" ADD CONSTRAINT "circle_discussions_circle_id_fkey" FOREIGN KEY ("circle_id") REFERENCES "circles"("id") ON DELETE CASCADE ON UPDATE CASCADE;
